{
  "tools": [
    {
      "name": "github_get_issue",
      "integration": "github",
      "category": "issues",
      "description": "Get details of a GitHub issue including title, description, state, author, labels, assignees, and comments count.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "workspace": {
            "type": "string",
            "description": "The GitHub owner/organization name"
          },
